/** 取图标：目录优先，其次按扩展名，最后按大类 */
export function kindIcon(entry) {
  if (!entry) return KIND.file;
  if (entry.d) return KIND.folder;
  const ext = String(entry.e || '').toLowerCase().replace(/^\./, '');
  const byExt = EXT[ext];
  if (byExt) return byExt;
  return KIND[entry.k] || KIND.file;
}

